import { Button, Collapse, Stack, Card } from '@bifrostui/react';

export default () => {
  const [open, setOpen] = useState(false);
  return (
    <Stack direction="column" spacing="16px">
      <Button
        onClick={() => {
          setOpen((prev) => !prev);
        }}
      >
        Toggle State
      </Button>

      {/* Only entry animation, no exit animation */}
      <Stack direction="row" spacing="16px" alignItems="center">
        <div style={{ width: '120px' }}>Entry Animation Only:</div>
        <Collapse
          in={open}
          direction="vertical"
          enter={true}
          exit={false}
          timeout={500}
        >
          <Card
            style={{
              background: '#CCCCCC',
              width: '100px',
              height: '80px',
              padding: '8px',
            }}
          >
            <div>Instant Exit, Smooth Entry</div>
          </Card>
        </Collapse>
      </Stack>

      {/* Only exit animation, no entry animation */}
      <Stack direction="row" spacing="16px" alignItems="center">
        <div style={{ width: '120px' }}>Exit Animation Only:</div>
        <Collapse
          in={open}
          direction="horizontal"
          enter={false}
          exit={true}
          timeout={500}
        >
          <Card
            style={{
              background: '#CCCCCC',
              width: '100px',
              height: '80px',
              padding: '8px',
            }}
          >
            <div>Instant Entry, Smooth Exit</div>
          </Card>
        </Collapse>
      </Stack>

      {/* Disable all animations */}
      <Stack direction="row" spacing="16px" alignItems="center">
        <div style={{ width: '120px' }}>All Disabled:</div>
        <Collapse in={open} direction="vertical" enter={false} exit={false}>
          <Card
            style={{
              background: '#CCCCCC',
              width: '100px',
              height: '80px',
              padding: '8px',
            }}
          >
            <div>Instant Switch, No Animation</div>
          </Card>
        </Collapse>
      </Stack>
    </Stack>
  );
};`},react:{type:"NPM",value:"19.2.5"}},entry:"index.tsx"},context:{react:m||(m=e.t(u,2))},renderOpts:{compile:function(){var i=y()(d()().mark(function a(){var r,n=arguments;return d()().wrap(function(t){for(;;)switch(t.prev=t.next){case 0:return t.next=2,e.e(8321).then(e.bind(e,78321));case 2:return t.abrupt("return",(r=t.sent).default.apply(r,n));case 3:case"end":return t.stop()}},a)}));function o(){return i.apply(this,arguments)}return o}()}}}},21152:function(F,O,e){var m;e.r(O),e.d(O,{demos:function(){return f}});var k=e(48305),d=e.n(k),$=e(90228),I=e.n($),S=e(87999),y=e.n(S),u=e(57393),f={"packages-bui-core-src-collapse-panel-demo-en-us-0":{component:u.memo(u.lazy(y()(I()().mark(function i(){var o,a,r;return I()().wrap(function(l){for(;;)switch(l.prev=l.next){case 0:return l.next=2,Promise.all([e.e(7235),e.e(7976),e.e(2225),e.e(4645)]).then(e.bind(e,64645));case 2:return o=l.sent,a=o.CollapsePanel,l.next=6,Promise.resolve().then(e.t.bind(e,57393,19));case 6:return r=l.sent,l.abrupt("return",{default:function(){var p=`
